var i=[{title:`Was Isolation bedeutet`,text:`Ein Bizeps-Curl beugt hauptsächlich den Ellbogen, und eine Trizepsstreckung streckt ihn. Seitheben betont die Schulterabduktion, Beinstrecken betonen die Kniestreckung, und Beinbeugen betonen die Kniebeugung. Keine echte Bewegung rekrutiert nur einen Muskel, „Isolation“ bedeutet also, dass die Bewegung auf ein Gelenk konzentriert ist, während andere Muskeln weiterhin helfen.`},{title:`Wann sie nützlich ist`,text:`Isolation kann einem zurückliegenden Muskel zusätzliche Arbeit geben, die Ermüdung des ganzen Körpers niedrig halten oder dir eine einfache Option bieten, wenn Gleichgewicht und Koordination schwerfallen. Rudern trainiert zum Beispiel indirekt den Bizeps, aber Curls geben einen direkteren Reiz, wenn Armwachstum Priorität hat. Maschinen können gezielte Anstrengung besonders leicht kontrollierbar machen.`},{title:`Wo sie in eine Einheit passt`,text:`Für allgemeine Kraft kommen Grundübungen meist zuerst, solange du frisch bist, und Isolationsarbeit folgt als zusätzliches Training. Wenn ein isolierter Muskel dein Hauptziel ist, ist es vernünftig, ihn früh zu trainieren. Die Übungsreihenfolge ist ein Weg, Prioritäten zu setzen, und du kannst sie ändern, wenn sich deine Prioritäten ändern.`},{title:`Technik und Steigerung`,text:`Nutze einen Bereich, der sich am Arbeitsgelenk bequem anfühlt, halte den Rest deines Körpers stabil und schwinge die Last nicht. Füge Wiederholungen oder etwas Gewicht nur hinzu, wenn deine Form von Wiederholung zu Wiederholung gleich bleibt. Sehr leichte Lasten funktionieren, wenn die Anstrengung hoch genug ist, und eine schwerere Zahl zu heben beweist nicht, dass das Training besser ist. Halte deine Gesamtsätze bei dem, was du verkraften kannst. Wenn eine Bewegung Schmerzen verursacht, brich sie ab; TrainUp gibt keine korrigierenden Reha-Programme vor.`}];var t=[{label:`ACSM-Positionspapier 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`ACE-Übungsbibliothek`,url:`https://www.acefitness.org/resources/everyone/exercise-library/`},{label:`Mayo Clinic: Technik beim Krafttraining (2026)`,url:`https://www.mayoclinic.org/healthy-lifestyle/fitness/in-depth/weight-training/art-20045842`}];var r={sections:i,sources:t};export{r as default,i as sections,t as sources};